// Runs inside the render container at job start: writes registry.gen.tsx from scenes/*.tsx.
import { readdirSync, writeFileSync } from "node:fs";
import path from "node:path";

const root = process.argv[2];
if (!root) throw new Error("usage: gen-registry.mjs <jobDir>");
const scenes = readdirSync(path.join(root, "scenes"))
  .filter((f) => f.endsWith(".tsx"))
  .map((f) => path.basename(f, ".tsx"))
  .filter((n) => /^[A-Za-z][A-Za-z0-9]*$/.test(n))
  .sort();
const src = [
  "// generated by gen-registry.mjs; do not edit",
  ...scenes.map((n) => `import ${n} from "./scenes/${n}";`),
  `export const registry = { ${scenes.join(", ")} };`,
  "",
].join("\n");
writeFileSync(path.join(root, "registry.gen.tsx"), src);
console.log(`registry: ${scenes.join(",")}`);
